<?php $pageTitle='Tournament Bracket';require_once __DIR__.'/includes/header.php';$t=active_tournament($pdo);$matches=[];if($t){$s=$pdo->prepare("SELECT m.*,p1.name p1_name,p1.seed p1_seed,p2.name p2_name,p2.seed p2_seed FROM matches m LEFT JOIN participants p1 ON p1.id=m.participant1_id LEFT JOIN participants p2 ON p2.id=m.participant2_id WHERE m.tournament_id=? ORDER BY round_number,match_number");$s->execute([$t['id']]);$matches=$s->fetchAll();$rounds=[];foreach($matches as $m)$rounds[$m['round_number']][]=$m;}?>
<main><section class="page-hero"><div class="container"><div class="eyebrow">Single elimination</div><h1>Tournament bracket</h1><p>Follow every matchup from the opening round to the championship.</p></div></section><section class="section"><div class="container"><div class="bracket-toolbar"><button class="btn btn-sm" data-zoom="out"><i class="fa-solid fa-minus"></i> Zoom</button><button class="btn btn-sm" data-zoom="in"><i class="fa-solid fa-plus"></i> Zoom</button><button class="btn btn-sm" data-zoom="reset"><i class="fa-solid fa-rotate-left"></i> Reset</button><button class="btn btn-sm" data-fullscreen><i class="fa-solid fa-expand"></i> Fullscreen</button></div><div class="bracket-viewport"><div class="bracket-canvas"><?php if(empty($matches)):?><div class="empty"><i class="fa-solid fa-sitemap"></i><h3>Bracket belum dibuat</h3></div><?php endif;foreach($rounds??[] as $roundMatches):?><section class="bracket-round"><h3><?=e($roundMatches[0]['round'])?></h3><div class="bracket-matches"><?php foreach($roundMatches as $m):$p1win=$m['winner_id']!==null&&(int)$m['winner_id']===(int)$m['participant1_id'];$p2win=$m['winner_id']!==null&&(int)$m['winner_id']===(int)$m['participant2_id'];?><a href="match.php?id=<?=$m['id']?>" class="bracket-match"><div class="bracket-team <?=$p1win?'winner':''?>"><span class="bracket-seed">#<?=e((string)($m['p1_seed']??'-'))?></span><span><?=e($m['p1_name']??'TBD')?></span><span class="bracket-score"><?=$m['score1']?><?=$p1win?' ✓':''?></span></div><div class="bracket-team <?=$p2win?'winner':''?>"><span class="bracket-seed">#<?=e((string)($m['p2_seed']??'-'))?></span><span><?=e($m['p2_name']??'TBD')?></span><span class="bracket-score"><?=$m['score2']?><?=$p2win?' ✓':''?></span></div><div class="bracket-status"><?=e($m['status'])?></div></a><?php endforeach;?></div></section><?php endforeach;?></div></div></div></section></main><script src="<?=BASE_URL?>/assets/js/bracket.js"></script>
